api_endpoints:
POST /v1/optimizer/exec/preview
  - payload: {customer_id, recommendation_id, simulate_options}
  - response: {diff, estimated_monthly_cost_delta, example_payloads}

POST /v1/optimizer/exec/apply
  - headers: Authorization: Bearer <svc-jwt>, Idempotency-Key: <uuid-v4>
  - payload: {customer_id, recommendation_id, dry_run:false, apply_window:{start,end}}
  - response 202: {operation_id, status:url} or 200 if idempotent repeat with same op_id

GET /v1/optimizer/exec/operation/{operation_id}
  - response: {operation_id, status, timeline:[{event,timestamp}], snapshot_ref}

POST /v1/optimizer/exec/operation/{operation_id}/rollback
  - headers: Authorization, Idempotency-Key
  - payload: {reason, force:false}
  - response 202: {rollback_op_id}
